export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'ref'> {
  size?: number | string
  weight?: IconWeight
  strokeWidth?: number | string
}
export type LucideIcon = ComponentType<IconProps>
export type AppIcon = LucideIcon

type PhIcon = ComponentType<{ size?: number | string; weight?: IconWeight; className?: string } & Record<string, unknown>>
function wrap(Ph: PhIcon, name: string): LucideIcon {
  const C = forwardRef<SVGSVGElement, IconProps>(function Icon({ size = 20, weight, strokeWidth, className, ...rest }, ref) {
    // strokeWidth > 2 maps to the bold weight so emphasised icons stay emphasised
    const w: IconWeight = weight ?? (Number(strokeWidth) >= 2.2 ? 'bold' : 'regular')
    return <Ph ref={ref} size={size} weight={w} className={className} aria-hidden={rest['aria-label'] ? undefined : true} {...rest} />
  })
  C.displayName = name
  return C as unknown as LucideIcon
}

